import { createRequestHandler } from "@react-router/cloudflare";
import * as build from "../server/index.js";

const serverBuild = (build && build.routes) ? build : ((build && build.default) || build);

const handleRequest = createRequestHandler({
  build: serverBuild,
  mode: "production",
});

export default {
  async fetch(request, env, ctx) {
    try {
      if (typeof globalThis !== "undefined") {
        globalThis.SLUGS_KV = env.SLUGS_KV;
        globalThis.__env__ = env;
      }

      if (env.ASSETS) {
        try {
          const url = new URL(request.url);
          if (url.pathname.startsWith('/assets/') || (url.pathname.includes('.') && !url.pathname.endsWith('.html'))) {
            const assetResponse = await env.ASSETS.fetch(request.url, request.clone());
            if (assetResponse && assetResponse.status >= 200 && assetResponse.status < 400) {
              return assetResponse;
            }
          }
        } catch {
          // ignore asset lookup error
        }
      }

      return await handleRequest({
        request,
        env,
        waitUntil: ctx.waitUntil ? ctx.waitUntil.bind(ctx) : () => {},
        passThroughOnException: ctx.passThroughOnException ? ctx.passThroughOnException.bind(ctx) : () => {},
      });
    } catch (err) {
      console.error("Worker fetch error:", err);
      return new Response("Server Error: " + (err?.stack || err?.message || err), { status: 500 });
    }
  },
};
